import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.DnrXFDHb.js";const c=JSON.parse('{"title":"推理与解码","description":"解释大模型自回归生成、Logit、Temperature、Top-k、Top-p、上下文窗口、KV Cache 与推理成本。","frontmatter":{"description":"解释大模型自回归生成、Logit、Temperature、Top-k、Top-p、上下文窗口、KV Cache 与推理成本。"},"headers":[],"relativePath":"llm/inference-decoding.md","filePath":"llm/inference-decoding.md","lastUpdated":1788335970000}'),i={name:"llm/inference-decoding.md"};function l(n,e,d,s,h,p){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="推理与解码" tabindex="-1">推理与解码 <a class="header-anchor" href="#推理与解码" aria-label="Permalink to &quot;推理与解码&quot;">​</a></h1><blockquote><p><strong>一句话结论：</strong> 自回归 LLM 每次根据已有上下文计算下一个 Token 的 Logit，再按解码策略选出 Token 并重复；采样参数改变的是选择方式，不会给模型增加知识或推理能力。</p></blockquote><h2 id="前置知识" tabindex="-1">前置知识 <a class="header-anchor" href="#前置知识" aria-label="Permalink to &quot;前置知识&quot;">​</a></h2><ul><li>已阅读 <a href="/llm/tokenization-embedding">Tokenization 与 Embedding</a>，知道文本会变成 Token ID 和向量。</li><li>已阅读 <a href="/llm/transformer">Transformer 直觉</a>，知道 Attention 会利用上下文形成表示。</li><li>不要求安装模型；本页示例只用手工概率推演。</li></ul><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><p>读完后，你应该能够：</p><ul><li>描述自回归生成从输入到停止的循环。</li><li>解释 Logit、Softmax 概率和“下一个 Token”的关系。</li><li>区分 Greedy、Temperature、Top-k 和 Top-p。</li><li>说明上下文窗口与 KV Cache 各自解决什么问题。</li><li>区分延迟、吞吐量和 Token 成本。</li><li>避免把采样参数当成事实性或能力开关。</li></ul><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><h3 id="自回归生成" tabindex="-1">自回归生成 <a class="header-anchor" href="#自回归生成" aria-label="Permalink to &quot;自回归生成&quot;">​</a></h3><p>多数生成式 LLM 采用自回归（Autoregressive）方式生成文本：</p><ol><li>Tokenizer 把输入编码成 Token ID。</li><li>模型读取当前上下文，计算 Vocabulary 中每个候选 Token 的 Logit。</li><li>解码策略选择一个下一个 Token。</li><li>把新 Token 追加到上下文。</li><li>重复计算，直到生成停止 Token、达到长度限制或触发其他停止条件。</li></ol><p>模型一次通常只提交一个新 Token，但界面可能把多个 Token 合并后再显示，所以用户看到的流式文字不一定逐 Token 刷新。</p><h3 id="logit、概率和下一个-token" tabindex="-1">Logit、概率和下一个 Token <a class="header-anchor" href="#logit、概率和下一个-token" aria-label="Permalink to &quot;Logit、概率和下一个 Token&quot;">​</a></h3><p>输出层会为 Vocabulary 中每个 Token 产生一个 <strong>Logit</strong>。Logit 是未归一化分数，可以是任意实数，不能直接当成概率。</p><p>Softmax 会把一组 Logit 转换为总和为 1 的概率分布。Logit 相对更高的 Token 会得到更高概率，但最终选谁取决于解码策略。</p><p>概率表达的是模型在当前参数和上下文下对候选 Token 的相对偏好，不是“这句话在现实中为真的概率”。</p><h3 id="greedy、temperature、top-k-与-top-p" tabindex="-1">Greedy、Temperature、Top-k 与 Top-p <a class="header-anchor" href="#greedy、temperature、top-k-与-top-p" aria-label="Permalink to &quot;Greedy、Temperature、Top-k 与 Top-p&quot;">​</a></h3><h4 id="greedy-decoding" tabindex="-1">Greedy Decoding <a class="header-anchor" href="#greedy-decoding" aria-label="Permalink to &quot;Greedy Decoding&quot;">​</a></h4><p>每一步都选择概率最高的 Token。结果通常确定、速度直接，但局部最优不保证整段文本最好，也可能产生重复或刻板输出。</p><h4 id="temperature" tabindex="-1">Temperature <a class="header-anchor" href="#temperature" aria-label="Permalink to &quot;Temperature&quot;">​</a></h4><p>Temperature 在 Softmax 前缩放 Logit：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>调整后 Logit = 原 Logit / Temperature</span></span></code></pre></div><ul><li>Temperature 小于 1：分布更尖锐，更偏向高分 Token。</li><li>Temperature 等于 1：保持原分布。</li><li>Temperature 大于 1：分布更平坦，低分 Token 更可能被抽到。</li></ul><p>数学上 Temperature 应大于 0。某些界面用 <code>0</code> 表示近似确定性行为，这是实现约定；需要确定输出时，更准确的概念是关闭采样或使用 Greedy。</p><h4 id="top-k" tabindex="-1">Top-k <a class="header-anchor" href="#top-k" aria-label="Permalink to &quot;Top-k&quot;">​</a></h4><p>只保留概率最高的 <code>k</code> 个 Token，再在其中重新归一化并采样。固定 <code>k</code> 不会根据当前分布的集中程度自动变化。</p><h4 id="top-p" tabindex="-1">Top-p <a class="header-anchor" href="#top-p" aria-label="Permalink to &quot;Top-p&quot;">​</a></h4><p>也叫 Nucleus Sampling。按概率从高到低累加，保留累计概率首次达到阈值 <code>p</code> 的最小候选集合，再重新归一化并采样。分布集中时集合较小，分布分散时集合会扩大。</p><p>实现还可能包含重复惩罚、长度惩罚和最小概率等处理，具体执行顺序应以目标推理框架文档为准。</p><h3 id="上下文窗口" tabindex="-1">上下文窗口 <a class="header-anchor" href="#上下文窗口" aria-label="Permalink to &quot;上下文窗口&quot;">​</a></h3><p>上下文窗口是模型单次推理可处理的 Token 总量，通常需要容纳：</p><ul><li>系统指令（System Prompt：平台或开发者预设的固定指令，用户看不到或不能改）与聊天模板。</li><li>用户输入和历史对话。</li><li>RAG 检索片段与工具结果。</li><li>已生成内容以及预留的后续输出空间。</li></ul><p>超过窗口时，框架可能报错、截断较早内容或使用滑动窗口。窗口更长会提高可容纳的信息量，也会增加内存和计算压力；但窗口大只说明装得多，不保证用得好——与任务无关的材料照样会拉低输出质量。</p><h3 id="kv-cache-的直觉" tabindex="-1">KV Cache 的直觉 <a class="header-anchor" href="#kv-cache-的直觉" aria-label="Permalink to &quot;KV Cache 的直觉&quot;">​</a></h3><p>Transformer Attention 会为 Token 计算 Key 和 Value。自回归生成第 100 个 Token 时，前 99 个 Token 的很多中间结果已经计算过。</p><p><strong>KV Cache</strong> 保存各层过去 Token 的 Key 和 Value，让下一步生成可以复用它们，而不必从头重复计算这些投影。它通常能明显加快逐 Token 解码，但代价是：</p><ul><li>序列越长，缓存通常占用越多显存或内存。</li><li>批量越大，同时保存的缓存越多。</li><li>KV Cache 不会扩大模型的上下文窗口。</li><li>它主要优化生成阶段的重复计算，首次处理整段输入的 Prefill（预填充，即把整段 Prompt 一次性算完前向的过程）仍需要计算输入 Token。</li></ul><h3 id="延迟、吞吐量和-token-成本" tabindex="-1">延迟、吞吐量和 Token 成本 <a class="header-anchor" href="#延迟、吞吐量和-token-成本" aria-label="Permalink to &quot;延迟、吞吐量和 Token 成本&quot;">​</a></h3><ul><li><strong>首 Token 延迟（Time to First Token, TTFT）</strong>：提交请求到看到第一个输出 Token 的时间，常受输入长度和 Prefill 影响。</li><li><strong>逐 Token 延迟（Inter-token Latency）</strong>：生成过程中相邻输出 Token 的等待时间。</li><li><strong>吞吐量（Throughput）</strong>：系统单位时间处理或生成多少 Token，批处理通常能提高总吞吐量，却可能增加单个请求等待。</li><li><strong>Token 成本</strong>：云服务可能分别计算输入、输出或缓存 Token；本地推理则对应计算、显存、内存和电力成本。</li></ul><p>“更低延迟”和“更高吞吐量”不是同一个目标。面向单人实时对话时更关注首 Token 和逐 Token 延迟；批量离线任务更关注总吞吐量。</p><h2 id="最小推演-三种候选-token" tabindex="-1">最小推演：三种候选 Token <a class="header-anchor" href="#最小推演-三种候选-token" aria-label="Permalink to &quot;最小推演：三种候选 Token&quot;">​</a></h2><p>假设模型对下一个 Token 给出三个 Logit：</p><table tabindex="0"><thead><tr><th>Token</th><th style="text-align:right;">Logit</th><th style="text-align:right;">Temperature = 1 时的概率</th></tr></thead><tbody><tr><td>A</td><td style="text-align:right;">2.0</td><td style="text-align:right;">66.5%</td></tr><tr><td>B</td><td style="text-align:right;">1.0</td><td style="text-align:right;">24.5%</td></tr><tr><td>C</td><td style="text-align:right;">0.0</td><td style="text-align:right;">9.0%</td></tr></tbody></table><p>Softmax 只关心相对差值。由此可以推演：</p><ul><li><strong>Greedy</strong>：一定选择 A。</li><li><strong>Temperature = 0.5</strong>：概率约变为 A 86.7%、B 11.7%、C 1.6%，分布更尖。</li><li><strong>Temperature = 2.0</strong>：概率约变为 A 50.6%、B 30.7%、C 18.6%，分布更平。</li><li><strong>Top-k = 2</strong>：移除 C，再把 A、B 归一化为约 73.1% 和 26.9%。</li><li><strong>Top-p = 0.8</strong>：A 单独只有 66.5%，加入 B 后累计 91.0%，所以保留 A 与 B。</li><li><strong>Top-p = 0.6</strong>：A 已超过阈值，因此候选集合只剩 A。</li></ul><p>这些操作只改变“从现有分布中怎样选”，不会修正错误知识。如果模型没有得到正确资料，调低 Temperature 可能只是让错误答案更稳定。</p><h2 id="对比表" tabindex="-1">对比表 <a class="header-anchor" href="#对比表" aria-label="Permalink to &quot;对比表&quot;">​</a></h2><p>把本页的解码方法和相关概念放在一起对比：</p><table tabindex="0"><thead><tr><th>方法或概念</th><th>主要作用</th><th>确定性</th><th>关键代价或风险</th></tr></thead><tbody><tr><td>Greedy</td><td>每步选最高概率 Token</td><td>高</td><td>可能重复、缺少多样性</td></tr><tr><td>Temperature</td><td>调整概率分布尖锐程度</td><td>取决于是否采样</td><td>过高会增加低概率输出</td></tr><tr><td>Top-k</td><td>限制为固定数量候选</td><td>通常采样</td><td>固定 k 不适应分布变化</td></tr><tr><td>Top-p</td><td>限制为动态累计概率集合</td><td>通常采样</td><td>p 过高会保留长尾噪声</td></tr><tr><td>上下文窗口</td><td>限制一次可处理的 Token 总量</td><td>不适用</td><td>长上下文增加计算和内存</td></tr><tr><td>KV Cache</td><td>复用过去 Token 的 Key/Value</td><td>不改变选择规则</td><td>以更多内存换取解码速度</td></tr></tbody></table><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><ul><li><strong>“Temperature 越低越准确”</strong>：它只让分布更集中，不能增加事实依据。</li><li><strong>“Top-p 和 Top-k 越大越聪明”</strong>：它们只控制候选集合和随机性。</li><li><strong>“Temperature = 0 是标准 Softmax”</strong>：数学公式要求 Temperature 大于 0，<code>0</code> 往往是界面约定。</li><li><strong>“KV Cache 会增加模型记忆长度”</strong>：它优化重复计算，不改变上下文上限。</li><li><strong>“上下文窗口全都可用于输出”</strong>：输入、历史、工具结果和输出通常共同占用窗口。</li><li><strong>“吞吐量高就代表每个用户更快”</strong>：批处理可能提高总吞吐量，同时增加单请求排队时间。</li><li><strong>“Token 数只影响账单”</strong>：它也影响延迟、显存、内存和可容纳上下文。</li></ul><h2 id="自测问题" tabindex="-1">自测问题 <a class="header-anchor" href="#自测问题" aria-label="Permalink to &quot;自测问题&quot;">​</a></h2><h3 id="_1-模型把某个-token-的概率设为-80-是否表示包含该-token-的事实有-80-可能为真" tabindex="-1">1. 模型把某个 Token 的概率设为 80%，是否表示包含该 Token 的事实有 80% 可能为真？ <a class="header-anchor" href="#_1-模型把某个-token-的概率设为-80-是否表示包含该-token-的事实有-80-可能为真" aria-label="Permalink to &quot;1. 模型把某个 Token 的概率设为 80%，是否表示包含该 Token 的事实有 80% 可能为真？&quot;">​</a></h3><details><summary>查看答案</summary><p>不是。这个概率表示模型在当前上下文下对下一个 Token 的相对偏好，不是对现实事实真假的校准概率。</p></details><h3 id="_2-top-k-5-与-top-p-0-9-的候选数量有什么区别" tabindex="-1">2. Top-k = 5 与 Top-p = 0.9 的候选数量有什么区别？ <a class="header-anchor" href="#_2-top-k-5-与-top-p-0-9-的候选数量有什么区别" aria-label="Permalink to &quot;2. Top-k = 5 与 Top-p = 0.9 的候选数量有什么区别？&quot;">​</a></h3><details><summary>查看答案</summary><p>Top-k 固定最多保留 5 个高概率候选；Top-p 保留累计概率达到 0.9 的最小集合，候选数量会随当前概率分布变化。</p></details><h3 id="_3-kv-cache-为什么能提速-又为什么会占用更多内存" tabindex="-1">3. KV Cache 为什么能提速，又为什么会占用更多内存？ <a class="header-anchor" href="#_3-kv-cache-为什么能提速-又为什么会占用更多内存" aria-label="Permalink to &quot;3. KV Cache 为什么能提速，又为什么会占用更多内存？&quot;">​</a></h3><details><summary>查看答案</summary><p>它保存过去 Token 在各层计算出的 Key 和 Value，下一步生成可以复用，减少重复计算；这些缓存需要随序列、层数和批量保存在显存或内存中。</p></details><h2 id="关联阅读" tabindex="-1">关联阅读 <a class="header-anchor" href="#关联阅读" aria-label="Permalink to &quot;关联阅读&quot;">​</a></h2><ul><li><strong>前置概念：</strong> <a href="/llm/transformer">Transformer 直觉</a>说明 Attention 如何利用上下文。</li><li><strong>同主题：</strong> <a href="/llm/training-alignment">训练、微调与对齐</a>解释生成时固定的参数是怎样形成的。</li><li><strong>应用方向：</strong> <a href="/prompting/basics">Prompt 入门</a>区分任务说明与采样参数各自能改变什么。</li></ul><h2 id="官方或原始资料来源" tabindex="-1">官方或原始资料来源 <a class="header-anchor" href="#官方或原始资料来源" aria-label="Permalink to &quot;官方或原始资料来源&quot;">​</a></h2><ul><li><a href="https://huggingface.co/docs/transformers/generation_strategies" target="_blank" rel="noreferrer">Hugging Face Transformers：Generation strategies</a>：解码策略（Greedy、采样、束搜索）的官方文档。</li><li><a href="https://huggingface.co/docs/transformers/main_classes/text_generation" target="_blank" rel="noreferrer">Hugging Face Transformers：Text generation API</a>：文本生成接口与参数的官方文档。</li><li><a href="https://huggingface.co/docs/transformers/kv_cache" target="_blank" rel="noreferrer">Hugging Face Transformers：Cache strategies</a>：KV Cache 等缓存机制的官方文档。</li><li><a href="https://huggingface.co/docs/transformers/llm_optims" target="_blank" rel="noreferrer">Hugging Face Transformers：LLM inference optimization</a>：推理优化与部署的官方指南。</li><li><a href="https://arxiv.org/abs/1904.09751" target="_blank" rel="noreferrer">Holtzman 等：The Curious Case of Neural Text Degeneration</a>：提出 Top-p（Nucleus）采样的原始论文。</li><li><a href="https://arxiv.org/abs/1706.03762" target="_blank" rel="noreferrer">Vaswani 等：Attention Is All You Need</a>：Transformer 架构的原始论文。</li></ul>',62)])])}const u=t(i,[["render",l]]);export{c as __pageData,u as default};
